def handle_create_user(body):
    # Check if body is a dict
    if not isinstance(body, dict):
        return (400, {"errors": {"body": "must be an object"}})

    # Validate name
    name = body.get('name')
    errors = {}

    if name is None:
        errors['name'] = "can't be blank"
    elif not isinstance(name, str):
        errors['name'] = "must be a string"
    elif not name.strip():
        errors['name'] = "can't be blank"
    else:
        name = name.strip()

    # Validate age
    age = body.get('age')
    if age is None:
        errors['age'] = "can't be blank"
    elif not isinstance(age, int):
        errors['age'] = "must be an integer"
    elif not (0 <= age <= 150):
        errors['age'] = "must be between 0 and 150"

    # Validate email
    email = body.get('email')
    if email is not None:
        if not isinstance(email, str):
            errors['email'] = "must be a string"
        elif email.count('@') != 1:
            errors['email'] = "must contain exactly one @ symbol"
        else:
            local_part, domain_part = email.split('@')
            if not local_part or not domain_part:
                errors['email'] = "must contain non-empty parts"

    # Return appropriate response
    if errors:
        return (422, {"errors": errors})

    return (201, {
        "name": name,
        "age": age,
        "email": email
    })
